import numpy as np, itertools
ats=[]
for l in open('opt4.xyz').read().splitlines()[2:]:
    p=l.split(); ats.append((p[0],np.array([float(x) for x in p[1:4]])))
els=[e for e,_ in ats]; n=len(ats)
def dist(a,b): return np.linalg.norm(ats[a][1]-ats[b][1])
# build bonded set (within typical bond cutoffs)
bonded=set()
cut={'H':{'H':0.0},}
def isbond(i,j):
    e1,e2=els[i],els[j]; d=dist(i,j)
    pairs={frozenset((e1,e2)):d}
    if 'H' in (e1,e2):
        return d<1.25
    return d<2.55  # includes Ga-C, Ga-N, Ni-Ga
for i,j in itertools.combinations(range(n),2):
    if isbond(i,j): bonded.add((i,j))
# clash check: non-bonded heavy atoms < 2.0, or H-H nonbonded < 1.6
bad=[]
for i,j in itertools.combinations(range(n),2):
    if (i,j) in bonded: continue
    d=dist(i,j)
    if els[i]=='H' or els[j]=='H':
        if d<1.55: bad.append((els[i],i,els[j],j,round(d,2)))
    else:
        if d<2.0: bad.append((els[i],i,els[j],j,round(d,2)))
print("bad contacts:", len(bad))
for b in bad[:20]: print(b)
# ring planarity for Cp*
for name,ring in [("Cp*1",range(4,9)),("Cp*2",range(30,35)),("Cp*3",range(56,61)),("LigRing",[85,86,87,88,89])]:
    pts=np.array([ats[c][1] for c in ring])
    cen=pts.mean(axis=0)
    # best plane
    u,s,vt=np.linalg.svd(pts-cen)
    dev=np.abs((pts-cen)@vt[2])
    print(name, "max out-of-plane dev:", f"{dev.max():.3f}")
